or(DLookUp("[ProovedorPrincipal]","[DBIngredientes]","[CodIngrediente]='" & [FiltroIngredienteVigentes]![CodIngrediente] & "'")) AS Proovedor, DLookUp("[ComprasSemana]","[DBIngredientes]","[CodIngrediente]='" & [FiltroIngredienteVigentes]![CodIngrediente] & "'")*7 AS [Dias Ciclo Compra], 0 AS [Dias Stock Minimo]
FROM FiltroIngredienteVigentes;

